package spec

import (
	"encoding/json"
	"os"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"testing"
	"time"
)

// The golden vectors (specdata/vectors/v0.json) are generated by the reference
// implementation. Every entry of every section must be reproduced byte for
// byte. The test walks whatever the file holds: a spec bump that adds a
// section fails here until the section is ported, so nothing is skipped silently.

func readVectors(t *testing.T) (map[string]json.RawMessage, int) {
	t.Helper()
	data, err := os.ReadFile("specdata/vectors/v0.json")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := ParseStrict(data); err != nil {
		t.Fatalf("the vectors file is not I-JSON: %v", err)
	}
	var top map[string]json.RawMessage
	if err := json.Unmarshal(data, &top); err != nil {
		t.Fatal(err)
	}
	return top, len(data)
}

func section(t *testing.T, top map[string]json.RawMessage, name string, into any) {
	t.Helper()
	raw, ok := top[name]
	if !ok {
		t.Fatalf("vectors have no section %q", name)
	}
	if err := json.Unmarshal(raw, into); err != nil {
		t.Fatalf("section %s: %v", name, err)
	}
}

func mustJCS(t *testing.T, v any) string {
	t.Helper()
	tree, err := Tree(v)
	if err != nil {
		t.Fatal(err)
	}
	b, err := JCS(tree)
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

func TestVectors(t *testing.T) {
	top, _ := readVectors(t)
	counts := map[string]int{}
	handled := map[string]bool{"spec_version": true, "note": true}
	use := func(name string) { handled[name] = true }

	// jcs
	use("jcs")
	var jcsRaw []map[string]string
	section(t, top, "jcs", &jcsRaw)
	for _, v := range jcsRaw {
		tree, err := ParseStrict([]byte(v["input_json"]))
		if err != nil {
			t.Errorf("jcs %q: %v", v["name"], err)
			continue
		}
		got, err := JCS(tree)
		if err != nil || string(got) != v["output"] {
			t.Errorf("jcs %q: got %q (%v), want %q", v["name"], got, err, v["output"])
		}
		counts["jcs"]++
	}

	// rejected_json
	use("rejected_json")
	var rejected []map[string]string
	section(t, top, "rejected_json", &rejected)
	for _, v := range rejected {
		if tree, err := ParseStrict([]byte(v["text"])); err == nil {
			t.Errorf("rejected_json %q: accepted as %v", v["name"], tree)
		}
		counts["rejected_json"]++
	}

	// op_hash
	use("op_hash")
	var ops []struct {
		Name   string         `json:"name"`
		Input  map[string]any `json:"input"`
		JCS    string         `json:"jcs"`
		OpHash string         `json:"op_hash"`
	}
	section(t, top, "op_hash", &ops)
	for _, v := range ops {
		if got := mustJCS(t, v.Input); got != v.JCS {
			t.Errorf("op_hash %q: jcs\n got %s\nwant %s", v.Name, got, v.JCS)
		}
		if got, err := OpHash(v.Input); err != nil || got != v.OpHash {
			t.Errorf("op_hash %q: got %s (%v), want %s", v.Name, got, err, v.OpHash)
		}
		counts["op_hash"]++
	}

	// approval_challenge
	use("approval_challenge")
	var chal []struct {
		Name      string         `json:"name"`
		Input     map[string]any `json:"input"`
		JCS       string         `json:"jcs"`
		Challenge string         `json:"challenge_sha256"`
	}
	section(t, top, "approval_challenge", &chal)
	for _, v := range chal {
		if got := mustJCS(t, v.Input); got != v.JCS {
			t.Errorf("approval_challenge %q: jcs\n got %s\nwant %s", v.Name, got, v.JCS)
		}
		approval := map[string]any{}
		for k, val := range v.Input {
			approval[k] = val
		}
		approval["approver"] = map[string]any{"id": approval["approver_id"]}
		approval["shown"] = map[string]any{"display_sha256": approval["display_sha256"]}
		delete(approval, "approver_id")
		delete(approval, "display_sha256")
		if got, err := ApprovalChallenge(approval); err != nil || got != v.Challenge {
			t.Errorf("approval_challenge %q: got %s (%v), want %s", v.Name, got, err, v.Challenge)
		}
		counts["approval_challenge"]++
	}

	// trace_id
	use("trace_id")
	var traces []struct {
		RunID   string `json:"run_id"`
		Chain   string `json:"chain"`
		TraceID string `json:"trace_id"`
	}
	section(t, top, "trace_id", &traces)
	for _, v := range traces {
		in := v.RunID
		if in == "" {
			in = v.Chain
		}
		if got := TraceID(in); got != v.TraceID {
			t.Errorf("trace_id %q: got %s, want %s", in, got, v.TraceID)
		}
		counts["trace_id"]++
	}

	// traceparent
	use("traceparent")
	var tps []struct {
		RunID       string `json:"run_id"`
		ParentID    string `json:"parent_id"`
		Flags       string `json:"flags"`
		Traceparent string `json:"traceparent"`
	}
	section(t, top, "traceparent", &tps)
	for _, v := range tps {
		got, err := TraceparentFor(v.RunID, v.ParentID, v.Flags)
		if err != nil || got != v.Traceparent {
			t.Errorf("traceparent %q: got %s (%v), want %s", v.RunID, got, err, v.Traceparent)
		}
		parsed, ok := ParseTraceparent(v.Traceparent)
		if !ok || parsed.TraceID != TraceID(v.RunID) || parsed.ParentID != v.ParentID || parsed.Flags != v.Flags {
			t.Errorf("traceparent %q: does not parse back to its parts: %+v", v.RunID, parsed)
		}
		counts["traceparent"]++
	}

	// usage_normalization
	use("usage_normalization")
	var usage []struct {
		Name       string         `json:"name"`
		Provider   string         `json:"provider"`
		Raw        map[string]any `json:"raw"`
		Attributes map[string]any `json:"attributes"`
	}
	section(t, top, "usage_normalization", &usage)
	for _, v := range usage {
		got, err := NormalizeUsage(v.Provider, v.Raw)
		if err != nil {
			t.Errorf("usage_normalization %q: %v", v.Name, err)
			continue
		}
		if g, w := mustJCS(t, got), mustJCS(t, v.Attributes); g != w {
			t.Errorf("usage_normalization %q:\n got %s\nwant %s", v.Name, g, w)
		}
		counts["usage_normalization"]++
	}

	// context_gate_files
	use("context_gate_files")
	var gate struct {
		Globs []string `json:"globs"`
		Cases []struct {
			Path     string `json:"path"`
			GateFile bool   `json:"gate_file"`
		} `json:"cases"`
	}
	section(t, top, "context_gate_files", &gate)
	if !reflect.DeepEqual(gate.Globs, ContextGateGlobs) {
		t.Errorf("context_gate_files globs: got %v, want %v", ContextGateGlobs, gate.Globs)
	}
	for _, v := range gate.Cases {
		if got := IsContextGateFile(v.Path); got != v.GateFile {
			t.Errorf("context_gate_files %q: got %v, want %v", v.Path, got, v.GateFile)
		}
		counts["context_gate_files"]++
	}

	// event_hash
	use("event_hash")
	var evs []struct {
		Name string         `json:"name"`
		Ev   map[string]any `json:"event_without_hash"`
		JCS  string         `json:"jcs"`
		Hash string         `json:"hash"`
	}
	section(t, top, "event_hash", &evs)
	for _, v := range evs {
		if got := mustJCS(t, v.Ev); got != v.JCS {
			t.Errorf("event_hash %q: jcs\n got %s\nwant %s", v.Name, got, v.JCS)
		}
		if got, err := EventHash(v.Ev); err != nil || got != v.Hash {
			t.Errorf("event_hash %q: got %s (%v), want %s", v.Name, got, err, v.Hash)
		}
		counts["event_hash"]++
	}

	// chains
	use("chains")
	var chains []struct {
		Name     string           `json:"name"`
		Expect   string           `json:"expect"`
		Problems []string         `json:"problems"`
		Events   []map[string]any `json:"events"`
	}
	section(t, top, "chains", &chains)
	for _, v := range chains {
		got := VerifyChain(v.Events)
		verdict := "pass"
		if len(got) > 0 {
			verdict = "fail"
		}
		if verdict != v.Expect {
			t.Errorf("chains %q: verdict %s, want %s (%v)", v.Name, verdict, v.Expect, got)
		}
		if !reflect.DeepEqual(append([]string{}, got...), append([]string{}, v.Problems...)) {
			t.Errorf("chains %q: problems\n got %q\nwant %q", v.Name, got, v.Problems)
		}
		counts["chains"]++
	}

	// requester_identity and vault_writes (spec v0.1.1)
	use("requester_identity")
	var identity []struct {
		Name     string    `json:"name"`
		Requests []Request `json:"requests"`
		Events   []Event   `json:"events"`
		Expect   string    `json:"expect"`
		Problems []string  `json:"problems"`
	}
	section(t, top, "requester_identity", &identity)
	for _, v := range identity {
		checkVerdict(t, "requester_identity", v.Name, CheckRequesterIdentity(v.Events, v.Requests), v.Expect, v.Problems)
		counts["requester_identity"]++
	}
	use("vault_writes")
	var vaults []struct {
		Name     string   `json:"name"`
		Events   []Event  `json:"events"`
		Expect   string   `json:"expect"`
		Problems []string `json:"problems"`
	}
	section(t, top, "vault_writes", &vaults)
	for _, v := range vaults {
		checkVerdict(t, "vault_writes", v.Name, CheckVaultWrites(v.Events), v.Expect, v.Problems)
		counts["vault_writes"]++
	}

	// run_tokens
	use("run_tokens")
	var tokens []struct {
		Name     string          `json:"name"`
		Now      string          `json:"now"`
		Profile  *GenericProfile `json:"profile"`
		Revoked  []string        `json:"revoked"`
		Claims   RunTokenClaims  `json:"claims"`
		Expect   string          `json:"expect"`
		Problems []string        `json:"problems"`
	}
	section(t, top, "run_tokens", &tokens)
	for _, v := range tokens {
		now, err := time.Parse(time.RFC3339Nano, v.Now)
		if err != nil {
			t.Fatalf("run_tokens %q: %v", v.Name, err)
		}
		revoked := map[string]bool{}
		for _, j := range v.Revoked {
			revoked[j] = true
		}
		got := CheckRunTokenClaims(v.Claims, v.Profile, TokenCheck{Now: now, Revoked: revoked})
		verdict := "pass"
		if len(got) > 0 {
			verdict = "fail"
		}
		if verdict != v.Expect {
			t.Errorf("run_tokens %q: verdict %s, want %s (%v)", v.Name, verdict, v.Expect, got)
		}
		if !reflect.DeepEqual(append([]string{}, got...), append([]string{}, v.Problems...)) {
			t.Errorf("run_tokens %q: problems\n got %q\nwant %q", v.Name, got, v.Problems)
		}
		counts["run_tokens"]++
	}

	// sha256_of_empty
	use("sha256_of_empty")
	var empty string
	section(t, top, "sha256_of_empty", &empty)
	if got := SHA256Tagged(nil); got != empty {
		t.Errorf("sha256_of_empty: got %s, want %s", got, empty)
	}
	counts["sha256_of_empty"]++

	var unknown []string
	for k := range top {
		if !handled[k] {
			unknown = append(unknown, k)
		}
	}
	if len(unknown) > 0 {
		sort.Strings(unknown)
		t.Errorf("vectors hold sections this package does not check: %s", strings.Join(unknown, ", "))
	}
	total := 0
	names := make([]string, 0, len(counts))
	for k, n := range counts {
		total += n
		names = append(names, k)
	}
	sort.Strings(names)
	var parts []string
	for _, k := range names {
		parts = append(parts, k+"="+strconv.Itoa(counts[k]))
	}
	t.Logf("vectors reproduced: %d entries (%s)", total, strings.Join(parts, " "))
}

// checkVerdict compares a check's problems with a vector's verdict and reference messages.
func checkVerdict(t *testing.T, section, name string, got []string, expect string, problems []string) {
	t.Helper()
	verdict := "pass"
	if len(got) > 0 {
		verdict = "fail"
	}
	if verdict != expect {
		t.Errorf("%s %q: verdict %s, want %s (%v)", section, name, verdict, expect, got)
	}
	if !reflect.DeepEqual(append([]string{}, got...), append([]string{}, problems...)) {
		t.Errorf("%s %q: problems\n got %q\nwant %q", section, name, got, problems)
	}
}
